def top_two_elements(nums):
    counts = {}

    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Sort the counts in descending order
    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)

    if len(sorted_counts) < 2:
        return None

    return [x[0] for x in sorted_counts[:2]]
